import json, csv, math
from pathlib import Path
root=Path('/root')
report=json.load(open(root/'reagent_policy_report.json'))
template=json.load(open(root/'report_template.json'))
summary=(root/'reagent_policy_summary.md').read_text().splitlines()
errors=[]
if report['metadata'] != template['metadata']:
    errors.append('metadata mismatch')
assays=report['analysis']['assays']
ids=[a['assay_id'] for a in assays]
if ids != sorted(ids):
    errors.append(f'assays not sorted: {ids}')
if report['analysis']['assumptions'] != {'runs_small':24,'runs_bulk':12,'switch_threshold_usd':7000}:
    errors.append('assumptions mismatch')
tot=report['analysis']['totals']
calc_small=round(sum(a['annual_margin_small_usd'] for a in assays),2)
calc_bulk=round(sum(a['annual_margin_bulk_usd'] for a in assays),2)
if (tot['total_annual_margin_small_kit_usd'], tot['total_annual_margin_bulk_kit_usd']) != (calc_small, calc_bulk):
    errors.append('totals mismatch')
calc_diff=round(calc_bulk-calc_small,2)
if tot['total_annual_margin_difference_bulk_minus_small_usd'] != calc_diff or tot['absolute_total_margin_difference_usd'] != round(abs(calc_diff),2):
    errors.append('diff mismatch')
expected='adopt_bulk_kit' if tot['absolute_total_margin_difference_usd'] < 7000 else 'keep_small_kit'
if report['analysis']['recommendation']['decision'] != expected:
    errors.append('decision mismatch')
nonempty=[line for line in summary if line.strip()]
if not (4 <= len(nonempty) <= 8): errors.append('markdown line count')
for needle in ['Total small-kit margin (USD)', 'Total bulk-kit margin (USD)', 'Absolute difference (USD)', f'Final decision: {expected}']:
    if not any(needle in line for line in nonempty): errors.append(f'missing md item {needle}')
# currency numeric rounded check for keys ending usd
for path,obj in [('root',report)]:
    def walk(x,p=''):
        if isinstance(x,dict):
            for k,v in x.items():
                if k.endswith('_usd') and isinstance(v,(int,float)) and round(float(v),2)!=float(v):
                    errors.append(f'currency not rounded {p}.{k}={v}')
                walk(v,p+'.'+k)
        elif isinstance(x,list):
            for i,v in enumerate(x): walk(v,p+f'[{i}]')
    walk(obj)
print('VALIDATION PASSED' if not errors else 'VALIDATION FAILED')
for e in errors: print(e)
print('assay_ids=', ids)
print('totals=', tot)
print('decision=', report['analysis']['recommendation']['decision'])
